import json
with open('after-cpm-packages.json') as f:
    data = json.load(f)
with open('baseline-packages-new.json') as f:
    base = json.load(f)

def get_pkgs(d):
    result = {}
    for proj in d.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for p in fw.get('topLevelPackages', []):
                key = (name, fw['framework'], p['id'])
                result[key] = p['resolvedVersion']
    return result

b = get_pkgs(base)
a = get_pkgs(data)
changes = []
for k in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(k, 'N/A')
    av = a.get(k, 'N/A')
    if bv != av:
        changes.append((k, bv, av))

if changes:
    print('VERSION CHANGES:')
    for (proj, fw, pkg), bv, av in changes:
        print(f'  {proj} ({fw}) {pkg}: {bv} -> {av}')
else:
    print('No version changes - conversion is version-neutral for unchanged packages')

# Show all resolved
print()
print('ALL RESOLVED PACKAGES:')
for k in sorted(a.keys()):
    proj, fw, pkg = k
    print(f'  {proj} ({fw}) {pkg}: {a[k]}')
"

